        if (shipments == null || shipments.isEmpty()) {
            return 0;
        }

        List<FB_Shipment_Event__e> events = new List<FB_Shipment_Event__e>();

        for (ShipmentEventPublisher.Shipment shipment : shipments) {
            if (String.isNotBlank(shipment.orderNumber)) {
                events.add(new FB_Shipment_Event__e(
                    Order_Number__c = shipment.orderNumber,
                    Tracking_Number__c = shipment.trackingNumber,
                    Carrier__c = shipment.carrier
                ));
            }
        }

        if (events.isEmpty()) {
            return 0;
        }

        EventBus.PublishResult[] results = EventBus.publish(events);

        Integer successCount = 0;
        for (EventBus.PublishResult result : results) {
            if (result.isSuccess()) {
                successCount++;
            }
        }

        return successCount;
    }
