public class AccountScoringJob implements Queueable {

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds != null ? accountIds : new List<Id>();
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return (Id) System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer processLimit = 200;
        Integer size = accountIds.size();

        List<Id> currentBatch = new List<Id>();
        List<Id> remainingBatch = new List<Id>();

        if (size <= processLimit) {
            currentBatch.addAll(accountIds);
        } else {
            for (Integer i = 0; i < processLimit; i++) {
                currentBatch.add(accountIds[i]);
            }
            for (Integer i = processLimit; i < size; i++) {
                remainingBatch.add(accountIds[i]);
            }
        }

        // Single SOQL Query
        List<Account> accounts = [SELECT Id, AnnualRevenue FROM Account WHERE Id IN :currentBatch];

        // Single DML Statement
        for (Account acc : accounts) {
            if (acc.AnnualRevenue != null && acc.AnnualRevenue >= 1000000) {
                acc.Rating = 'Hot';
            } else if (acc.AnnualRevenue != null && acc.AnnualRevenue >= 100000) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
        }

        update accounts;

        // Chain if there are remaining IDs
        if (!remainingBatch.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remainingBatch));
        }
    }
}
