public with sharing class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : accountIds;
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before doing any work.
        System.attachFinalizer(new ErpSyncFinalizer(this.accountIds, this.attempt));

        // Build the records directly from the Ids so that any account that
        // cannot be saved (e.g. does not exist or fails a validation rule)
        // causes an unhandled exception -> the whole job fails.
        List<Account> accounts = new List<Account>();
        for (Id accId : this.accountIds) {
            accounts.add(new Account(Id = accId, Description = 'Synced to ERP'));
        }

        if (!accounts.isEmpty()) {
            // all-or-nothing: any failure throws, nothing is persisted.
            Database.update(accounts, true);
        }
    }
}
