public with sharing class ErpSyncFinalizer implements Finalizer {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : accountIds;
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        AsyncApexJob.Status status = context.getStatus();
        Boolean failed = status != AsyncApexJob.Status.Completed;

        FB_Job_Log__c log = new FB_Job_Log__c();
        log.Job_Name__c = 'ErpAccountSyncJob';
        log.Attempt__c = this.attempt;

        if (!failed) {
            log.Status__c = 'Success';
        } else {
            log.Status__c = 'Failed';

            // Derive the exception message from the finalizer context.
            // getResult() may carry either the Exception itself or its message.
            Object result = context.getResult();
            String errorMsg;
            if (result instanceof Exception) {
                errorMsg = ((Exception) result).getMessage();
            } else if (result != null) {
                errorMsg = String.valueOf(result);
            } else {
                errorMsg = '';
            }

            if (errorMsg != null && errorMsg.length() > 255) {
                errorMsg = errorMsg.substring(0, 255);
            }
            log.Error__c = errorMsg;
        }

        insert log;

        // Retry up to 3 attempts total. After the third failed attempt, stop.
        if (failed && this.attempt < 3) {
            System.enqueueJob(new ErpAccountSyncJob(this.accountIds, this.attempt + 1));
        }
    }
}
