public with sharing class OpportunityPipelineHandler {

    @TestVisible
    private static Boolean isProcessing = false;

    // ─────────────────────────────────────────────────────────────
    // Public entry points called from the trigger
    // ─────────────────────────────────────────────────────────────

    public static void afterInsert(Map<Id, Opportunity> newMap) {
        Set<Id> accountIds = collectAccountIds(newMap.values());
        recalculate(accountIds);
    }

    public static void afterUpdate(Map<Id, Opportunity> oldMap, Map<Id, Opportunity> newMap) {
        Set<Id> accountIds = new Set<Id>();
        accountIds.addAll(collectAccountIds(oldMap.values()));
        accountIds.addAll(collectAccountIds(newMap.values()));
        recalculate(accountIds);
    }

    public static void afterDelete(Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = collectAccountIds(oldMap.values());
        recalculate(accountIds);
    }

    public static void afterUndelete(Map<Id, Opportunity> newMap) {
        Set<Id> accountIds = collectAccountIds(newMap.values());
        recalculate(accountIds);
    }

    // ─────────────────────────────────────────────────────────────
    // Core logic: recompute open-pipeline totals from the database
    // and write them back to the affected Accounts.
    // ─────────────────────────────────────────────────────────────

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }
        // Recursion guard: prevents infinite loop when this handler
        // updates Account → AccountTrigger fires → updates Opportunity
        // → this trigger fires again.
        if (isProcessing) {
            return;
        }
        isProcessing = true;
        try {
            // 1. Aggregate open opportunities per account
            Map<Id, Decimal> totalMap = new Map<Id, Decimal>();
            Map<Id, Decimal> countMap = new Map<Id, Decimal>();

            for (AggregateResult ar : [
                SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) oppCount
                FROM Opportunity
                WHERE IsClosed = false
                  AND AccountId IN :accountIds
                GROUP BY AccountId
            ]) {
                Id accId = (Id) ar.get('AccountId');
                Decimal amt = (Decimal) ar.get('totalAmount');
                Decimal cnt = (Decimal) ar.get('oppCount');
                totalMap.put(accId, amt != null ? amt : Decimal.valueOf(0));
                countMap.put(accId, cnt != null ? cnt : Decimal.valueOf(0));
            }

            // 2. Read current Account field values to avoid unnecessary DML
            Map<Id, Account> currentAccounts = new Map<Id, Account>();
            for (Account acc : [
                SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
                FROM Account
                WHERE Id IN :accountIds
            ]) {
                currentAccounts.put(acc.Id, acc);
            }

            // 3. Build update list only for accounts whose values actually changed
            List<Account> toUpdate = new List<Account>();
            for (Id accId : accountIds) {
                Decimal expectedTotal = totalMap.containsKey(accId)
                    ? totalMap.get(accId) : Decimal.valueOf(0);
                Decimal expectedCount = countMap.containsKey(accId)
                    ? countMap.get(accId) : Decimal.valueOf(0);

                Account existing = currentAccounts.get(accId);
                if (existing == null) {
                    continue;
                }

                Decimal curTotal = existing.FB_Open_Pipeline__c != null
                    ? existing.FB_Open_Pipeline__c : Decimal.valueOf(0);
                Decimal curCount = existing.FB_Open_Opportunities__c != null
                    ? existing.FB_Open_Opportunities__c : Decimal.valueOf(0);

                if (curTotal != expectedTotal || curCount != expectedCount) {
                    toUpdate.add(new Account(
                        Id = accId,
                        FB_Open_Pipeline__c = expectedTotal,
                        FB_Open_Opportunities__c = expectedCount
                    ));
                }
            }

            // 4. Bulk-safe single DML (supports 200+ opportunities / many accounts)
            if (!toUpdate.isEmpty()) {
                update toUpdate;
            }
        } finally {
            isProcessing = false;
        }
    }

    // ─────────────────────────────────────────────────────────────
    // Helpers
    // ─────────────────────────────────────────────────────────────

    private static Set<Id> collectAccountIds(List<Opportunity> opps) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity opp : opps) {
            if (opp.AccountId != null) {
                ids.add(opp.AccountId);
            }
        }
        return ids;
    }
}
