    private class DomainFactory implements fflib_Application.DomainFactory {
        private final Map<SObjectType, fflib_SObjectDomain.IConstructable> m_factories =
            new Map<SObjectType, fflib_SObjectDomain.IConstructable>{
                Account.SObjectType => new Accounts.Constructor()
            };

        public fflib_SObjectDomain newInstance(SObjectType sObjectType) {
            return m_factories.get(sObjectType).construct(new List<SObject>());
        }

        public fflib_SObjectDomain newInstance(Set<Id> recordIds) {
            Map<SObjectType, Set<Id>> idsByType = groupIdsByType(recordIds);

            if (idsByType.size() != 1) {
                throw new ApplicationException(
                    'newInstance(Set<Id>) requires all Ids to be of the same SObjectType'
                );
            }

            SObjectType sType = idsByType.keySet().iterator().next();
            Set<Id> ids = idsByType.get(sType);
            List<SObject> records = Application.Selector.newInstance(sType).selectById(ids);
            return m_factories.get(sType).construct(records);
        }

