            Map<SObjectType, Set<Id>> idsByType = groupIdsByType(recordIds);
            Map<SObjectType, fflib_SObjectDomain> domains =
                new Map<SObjectType, fflib_SObjectDomain>();

            for (SObjectType sType : idsByType.keySet()) {
                Set<Id> ids = idsByType.get(sType);
                List<SObject> records = Application.Selector.newInstance(sType).selectById(ids);
                domains.put(sType, m_factories.get(sType).construct(records));
            }
            return domains;
        }

        private Map<SObjectType, Set<Id>> groupIdsByType(Set<Id> recordIds) {
            Map<SObjectType, Set<Id>> idsByType = new Map<SObjectType, Set<Id>>();
            for (Id recordId : recordIds) {
                SObjectType sType = recordId.getSObjectType();
                if (!idsByType.containsKey(sType)) {
                    idsByType.put(sType, new Set<Id>());
                }
                idsByType.get(sType).add(recordId);
            }
            return idsByType;
        }
    }
