public inherited sharing class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load via selector (single bulk SOQL)
        List<Opportunity> opps = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Keep only those not already Closed Won, then apply the change
        Date today = Date.today();
        List<Opportunity> toClose = new List<Opportunity>();
        for (Opportunity opp : opps) {
            if (opp.StageName != 'Closed Won') {
                opp.StageName = 'Closed Won';
                opp.CloseDate = today;
                toClose.add(opp);
            }
        }

        if (toClose.isEmpty()) {
            return 0;
        }

        // One fflib unit of work. The concrete fflib_SObjectUnitOfWork is used (not the
        // interface) because that is what exposes registerPublish()/commit() in this
        // fflib build. registerPublish() queues each platform event and publishes it
        // only AFTER the DML inside commit() succeeds; if DML throws, commit() propagates
        // the exception and no event is ever published -> caller never hears about a
        // deal that was not actually saved. EventBus.publish() is never called directly.
        fflib_SObjectUnitOfWork uow =
            (fflib_SObjectUnitOfWork) Application.UnitOfWork.newInstance();

        for (Opportunity opp : toClose) {
            uow.registerDirty(opp);

            Deal_Won__e evt = new Deal_Won__e();
            evt.Opportunity_Id__c = opp.Id;
            evt.Amount__c = opp.Amount;
            uow.registerPublish(evt);
        }

        // Single commit: DML first, events published only on success.
        uow.commit();

        return toClose.size();
    }
}
