File: force-app/main/default/triggers/CaseTrigger.trigger
```apex
trigger CaseTrigger on Case (after update) {
    if (!Trigger.isAfter || !Trigger.isUpdate) return;

    // ── Collect only the cases that just flipped to Closed AND have a Contact ──
    List<Id> eligibleCaseIds = new List<Id>();
    for (Case c : Trigger.new) {
        Case old = Trigger.oldMap.get(c.Id);
        if (c.IsClosed && !old.IsClosed && c.ContactId != null) {
            eligibleCaseIds.add(c.Id);
        }
    }

    // ── Enqueue one job per case (bulk-safe: chunk to respect the 50-job limit) ──
    // Salesforce allows at most 50 Queueable jobs per transaction.
    final Integer MAX_PER_TXN = 50;
    for (Integer i = 0; i < eligibleCaseIds.size(); i += MAX_PER_TXN) {
        Integer upper = Math.min(i + MAX_PER_TXN, eligibleCaseIds.size());
        for (Integer j = i; j < upper; j++) {
            System.enqueueJob(new CaseSurveyJob(eligibleCaseIds[j]));
        }
    }
}
```

