        const caseListViewPageReference = {
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Case',
                actionName: 'list'
            },
            state: {
                filterName: 'My_Open_Cases'
            }
        };

        this[NavigationMixin.GenerateUrl](caseListViewPageReference)
            .then((url) => {
                this.casesUrl = url;
            })
            .catch(() => {
                this.casesUrl = null;
            });
    }

    handleNavigate(event) {
        const source = event.currentTarget || event.target;
        const action = source && source.dataset ? source.dataset.action : null;

        if (!action || !this.recordId) {
            return;
        }

        let pageReference;

        switch (action) {
            case 'new-contact':
                pageReference = {
                    type: 'standard__objectPage',
                    attributes: {
                        objectApiName: 'Contact',
                        actionName: 'new'
                    },
                    state: {
                        defaultFieldValues: encodeDefaultFieldValues({
                            AccountId: this.recordId
                        })
                    }
                };
                break;

            case 'contacts':
                pageReference = {
                    type: 'standard__recordRelationshipPage',
                    attributes: {
                        recordId: this.recordId,
                        objectApiName: 'Account',
                        relationshipApiName: 'Contacts',
                        actionName: 'view'
                    }
                };
                break;

            case 'edit':
                pageReference = {
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: this.recordId,
                        objectApiName: 'Account',
                        actionName: 'edit'
                    }
                };
                break;

            default:
                return;
        }

        this[NavigationMixin.Navigate](pageReference);
