    contactsResult(result) {
        this._wiredContactsResult = result;
        const { error, data } = result;
        if (error) {
            this.contacts = [];
        } else if (data) {
            this.contacts = data;
        }
    }

    handleSave(event) {
        const drafts = event.detail.draftValues || [];

        // One updateRecord call per draft row. The draft already carries the
        // Id, so the field map is passed straight into `fields`.
        const recordInputs = drafts.map((draft) => ({ fields: { ...draft } }));
        const promises = recordInputs.map((recordInput) =>
            updateRecord(recordInput)
        );

        Promise.all(promises)
            .then(() => {
                this.draftValues = [];
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Contacts updated',
                        variant: 'success'
                    })
                );
                return refreshApex(this._wiredContactsResult);
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Could not save contacts',
                        message: error.body.message,
                        variant: 'error'
                    })
                );
            });
    }
}
