import { LightningElement, api } from 'lwc';
import addLabel from '@salesforce/label/c.Favorite_Add';
import removeLabel from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    // Public state owned by the parent. We never reassign it ourselves, so the
    // component is compliant with @lwc/lwc/no-api-reassignments.
    @api favorite = false;

    // Internal optimistic value. When set, it takes precedence over @api favorite
    // until the parent pushes a new value down.
    override = null;

    // Bookkeeping used only inside rendered() to know when the parent changed
    // favorite and we must therefore drop the stale optimistic value.
    lastRenderedFavorite = undefined;

    get shownFavorite() {
        return this.override === null ? this.favorite : this.override;
    }

    get pressed() {
        return this.shownFavorite ? 'true' : 'false';
    }

    get actionLabel() {
        return this.shownFavorite ? removeLabel : addLabel;
    }

    get iconName() {
        return this.shownFavorite ? 'utility:favorite' : 'utility:favorite_outline';
    }

    renderedCallback() {
        // Whenever the parent (e.g. after a server refresh) changes favorite,
        // clear any optimistic override so the button reflects the new value.
        if (this.favorite !== this.lastRenderedFavorite) {
            this.override = null;
            this.lastRenderedFavorite = this.favorite;
        }
    }

    handleClick() {
        const next = !this.shownFavorite;
        // Optimistic UI: flip the displayed value immediately.
        this.override = next;
        this.dispatchEvent(new CustomEvent('favoritechange', { detail: { favorite: next } }));
    }
}
