export default class OrderLinesPanel extends LightningElement {
    @api lines = [];
    showError = false;

    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach((editor) => {
            editor.reset();
        });
    }

    handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        let allValid = true;

        // Validate every editor, even after one reports a problem,
        // so that all invalid lines show their errors at once.
        editors.forEach((editor) => {
            const valid = editor.validate();
            if (!valid) {
                allValid = false;
            }
        });

        if (allValid) {
            const values = [...editors].map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines: values }
                })
            );
            this.showError = false;
        } else {
            this.showError = true;
        }
    }
}
