import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    stats = null;
    error = null;
    _inFlight = false;
    _intervalId = null;
    _visibilityHandler = null;

    connectedCallback() {
        this._visibilityHandler = this._onVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this._visibilityHandler);
        this._startPolling();
        this._fetchStats();
    }

    disconnectedCallback() {
        this._stopPolling();
        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = null;
        }
        this._inFlight = false;
    }

    _startPolling() {
        this._stopPolling();
        this._intervalId = setInterval(() => {
            if (document.visibilityState !== 'hidden' && !this._inFlight) {
                this._fetchStats();
            }
        }, POLL_INTERVAL_MS);
    }

    _stopPolling() {
        if (this._intervalId) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    _onVisibilityChange() {
        if (document.visibilityState === 'hidden') {
            this._stopPolling();
        } else {
            // Page became visible: load immediately and restart 60 s loop
            this._fetchStats();
            this._startPolling();
        }
    }

    _fetchStats() {
        if (this._inFlight) {
            return;
        }
        this._inFlight = true;
        getQueueStats()
            .then((result) => {
                this.stats = result;
                this.error = null;
                this._inFlight = false;
            })
            .catch((err) => {
                this.error = err.body.message;
                this._inFlight = false;
            });
    }
}
