import { LightningElement, api } from 'lwc';

/**
 * statusListbox
 *
 * A single-select ARIA listbox. The DOM focus is kept on the <ul role="listbox">
 * element and the "active" option is referenced through aria-activedescendant,
 * following the WAI-ARIA listbox pattern.
 */
export default class StatusListbox extends LightningElement {
    @api label = '';

    /**
     * The unique id of the host instance is used to namespace option ids so
     * that multiple instances on the same page do not collide.
     */
    baseId = `statusListbox-${this.constructor.name}-${Math
        .floor(Math.random() * 1e12)
        .toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

    _options = [];
    _value = '';
    activeIndex = 0;

    // ---------------------------------------------------------------------
    // Reactive API
    // ---------------------------------------------------------------------

    get options() {
        return this._options;
    }

    @api
    set options(value) {
        this._options = Array.isArray(value) ? value.slice() : [];
        this.syncActiveFromValue();
    }

    get value() {
        return this._value;
    }

    @api
    set value(value) {
        this._value = value == null ? '' : value;
        this.syncActiveFromValue();
    }

    // ---------------------------------------------------------------------
    // Internal helpers
    // ---------------------------------------------------------------------

    /**
     * When the selected value changes (either through user interaction or
     * because the parent reassigned `value`) the active option must move to
     * the selected option. If nothing is selected the active option is the
     * first option.
     */
    syncActiveFromValue() {
        const idx = this._options.findIndex((o) => o && o.value === this._value);
        this.activeIndex = idx >= 0 ? idx : 0;
    }

    /** Returns the options enriched with stable ids and aria-selected strings. */
    get enrichedOptions() {
        return this._options.map((o, i) => ({
            id: this.getOptionId(i),
            value: o.value,
            label: o.label,
            selected: o.value === this._value ? 'true' : 'false'
        }));
    }

    getOptionId(index) {
        return `${this.baseId}-option-${index}`;
    }

    get ariaActiveDescendant() {
        if (!this._options || this._options.length === 0) {
            return undefined;
        }
        return this.getOptionId(this.activeIndex);
    }

    get selectedIndex() {
        return this._options.findIndex((o) => o && o.value === this._value);
    }

    // ---------------------------------------------------------------------
    // Keyboard interaction
    // ---------------------------------------------------------------------

    handleKeydown(event) {
        const lastIndex = this._options.length - 1;
        if (lastIndex < 0) {
            return;
        }

        const key = event.key;
        let handled = true;

        switch (key) {
            case 'ArrowDown':
                if (this.activeIndex < lastIndex) {
                    this.activeIndex += 1;
                }
                break;
            case 'ArrowUp':
                if (this.activeIndex > 0) {
                    this.activeIndex -= 1;
                }
                break;
            case 'Home':
                this.activeIndex = 0;
                break;
            case 'End':
                this.activeIndex = lastIndex;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this.activeIndex);
                break;
            default:
                // Every other key (notably Tab) keeps its default behaviour.
                handled = false;
        }

        if (handled) {
            event.preventDefault();
        }
    }

    // ---------------------------------------------------------------------
    // Pointer interaction
    // ---------------------------------------------------------------------

    handleClick(event) {
        const li = event.target && event.target.closest('li[role="option"]');
        if (!li) {
            return;
        }
        const value = li.dataset.value;
        const index = this._options.findIndex((o) => o.value === value);
        if (index < 0) {
            return;
        }
        this.activeIndex = index;
        this.selectOption(index);
    }

    // ---------------------------------------------------------------------
    // Selection
    // ---------------------------------------------------------------------

    selectOption(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        // Selecting the already-selected option is a no-op (no event dispatched).
        if (option.value === this._value) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                bubbles: true,
                composed: true,
                detail: { value: option.value }
            })
        );
    }
}
