import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading;
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get heading() {
        return this._heading;
    }

    set heading(value) {
        this._heading = value;
    }

    get displayHeading() {
        return this._heading ? this._heading.toUpperCase() : '';
    }

    @api
    get tasks() {
        return this.items.map((t) => ({ id: t.id, label: t.label, done: t.done }));
    }

    set tasks(value) {
        this.items = value
            ? value.map((t) => ({ id: t.id, label: t.label, done: !!t.done }))
            : [];
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = this.newLabel ? this.newLabel.trim() : '';
        if (!label) {
            return;
        }

        const newItem = { id: `new-${this.nextId++}`, label, done: false };
        this.items = [...this.items, newItem];
        this.newLabel = '';

        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label },
                bubbles: true,
                composed: true
            })
        );
    }

    handleToggle(event) {
        const id = event.currentTarget.dataset.id;
        this.items = this.items.map((t) =>
            t.id === id ? { ...t, done: !t.done } : t
        );
    }
}
