public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) return;

        // Collect distinct Ids for bulk queries
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // SOQL 1: Opportunities for validation (amount + primary contact)
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // Validate ALL requests before any DML – throw on first violation
        for (SoftCreditRequest req : requests) {
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException(
                    'Soft credit amount must be positive and non-null.');
            }
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + req.opportunityId);
            }
            if (req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount exceeds opportunity amount.');
            }
            if (opp.npsp__Primary_Contact__c != null
                && opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'Contact cannot be the primary contact for soft credit.');
            }
        }

        // SOQL 2: Existing OpportunityContactRoles for these opp/contact pairs
        Map<Id, Map<Id, OpportunityContactRole>> ocrMap =
            new Map<Id, Map<Id, OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
              AND ContactId     IN :contactIds
        ]) {
            if (!ocrMap.containsKey(ocr.OpportunityId)) {
                ocrMap.put(ocr.OpportunityId, new Map<Id, OpportunityContactRole>());
            }
            ocrMap.get(ocr.OpportunityId).put(ocr.ContactId, ocr);
        }

        // SOQL 3: Existing Partial Soft Credits for these opp/contact pairs
        Map<Id, Map<Id, npsp__Partial_Soft_Credit__c>> pscMap =
            new Map<Id, Map<Id, npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
              AND npsp__Contact__c     IN :contactIds
        ]) {
            if (!pscMap.containsKey(psc.npsp__Opportunity__c)) {
                pscMap.put(psc.npsp__Opportunity__c,
                    new Map<Id, npsp__Partial_Soft_Credit__c>());
            }
            pscMap.get(psc.npsp__Opportunity__c).put(psc.npsp__Contact__c, psc);
        }

        // ---------- Determine OCM operations ----------
        // Keep a reference per request so the Id is available after DML
        OpportunityContactRole[] ocrPerReq =
            new OpportunityContactRole[requests.size()];
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests[i];
            Map<Id, OpportunityContactRole> contactMap =
                ocrMap.get(req.opportunityId);
            OpportunityContactRole ocr =
                (contactMap != null) ? contactMap.get(req.contactId) : null;

            if (ocr != null) {
                if (ocr.Role != req.role) {
                    ocr.Role = req.role;
                    ocrsToUpdate.add(ocr);
                }
                ocrPerReq[i] = ocr;
            } else {
                ocr = new OpportunityContactRole();
                ocr.OpportunityId = req.opportunityId;
                ocr.ContactId     = req.contactId;
                ocr.Role          = req.role;
                ocrsToInsert.add(ocr);
                ocrPerReq[i] = ocr;
            }
        }

        // DML 1 & 2: OCMs (reference keeps Id available after insert/update)
        if (!ocrsToInsert.isEmpty()) insert ocrsToInsert;
        if (!ocrsToUpdate.isEmpty()) update ocrsToUpdate;

        // ---------- Determine PSC operations ----------
        List<npsp__Partial_Soft_Credit__c> pscsToInsert =
            new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate =
            new List<npsp__Partial_Soft_Credit__c>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests[i];
            Id ocrId = ocrPerReq[i].Id;

            Map<Id, npsp__Partial_Soft_Credit__c> contactMap =
                pscMap.get(req.opportunityId);
            npsp__Partial_Soft_Credit__c psc =
                (contactMap != null) ? contactMap.get(req.contactId) : null;

            if (psc != null) {
                psc.npsp__Amount__c         = req.amount;
                psc.npsp__Role_Name__c      = req.role;
                psc.npsp__Contact_Role_ID__c = String.valueOf(ocrId);
                pscsToUpdate.add(psc);
            } else {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c    = req.opportunityId,
                    npsp__Contact__c        = req.contactId,
                    npsp__Amount__c         = req.amount,
                    npsp__Role_Name__c      = req.role,
                    npsp__Contact_Role_ID__c = String.valueOf(ocrId)
                );
                pscsToInsert.add(psc);
            }
        }

        // DML 3 & 4: PSCs
        if (!pscsToInsert.isEmpty()) insert pscsToInsert;
        if (!pscsToUpdate.isEmpty()) update pscsToUpdate;
