```apex
/**
 * Bulk-safe service to link parents and children in NPSP Relationships.
 *
 * Creates a child → parent relationship of type "Parent" (status "Current").
 * NPSP's "List Setting" reciprocal method automatically creates the
 * parent → child reciprocal (Son / Daughter / Child) during the same
 * DML transaction via the Relationship__c trigger.
 *
 * Governor budget for ≤ 200 pairs: 1 SOQL + 1 DML of our own code.
 */
public with sharing class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Guard: null / empty
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // ── 1. Build the full set of contact IDs involved ──────────────────
        Set<Id> childIds  = parentIdByChildId.keySet();
        Set<Id> parentIds = new Set<Id>(parentIdByChildId.values());

        Set<Id> allIds = new Set<Id>();
        allIds.addAll(childIds);
        allIds.addAll(parentIds);

        // ── 2. Single SOQL: find every existing Relationship__c that
        //       touches any of our contacts (either direction).
        List<npe4__Relationship__c> existingRels = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allIds
               OR npe4__RelatedContact__c IN :allIds
        ];

        // ── 3. Index existing relationships into a bidirectional adjacency map
        Map<Id, Set<Id>> adjacencies = new Map<Id, Set<Id>>();
        for (npe4__Relationship__c rel : existingRels) {
            if (!adjacencies.containsKey(rel.npe4__Contact__c)) {
                adjacencies.put(rel.npe4__Contact__c, new Set<Id>());
            }
            adjacencies.get(rel.npe4__Contact__c).add(rel.npe4__RelatedContact__c);

            if (!adjacencies.containsKey(rel.npe4__RelatedContact__c)) {
                adjacencies.put(rel.npe4__RelatedContact__c, new Set<Id>());
            }
            adjacencies.get(rel.npe4__RelatedContact__c).add(rel.npe4__Contact__c);
        }

        // ── 4. Build the insert list (child → parent), skipping existing pairs
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : childIds) {
            Id parentId = parentIdByChildId.get(childId);

            // If any relationship already exists between these two contacts
            // in either direction, skip the pair (safe re-run / idempotency).
            Set<Id> childAdj = adjacencies.get(childId);
            Set<Id> parentAdj = adjacencies.get(parentId);
            if ((childAdj != null && childAdj.contains(parentId)) ||
                (parentAdj != null && parentAdj.contains(childId))) {
                continue;
            }

            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c       = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c          = 'Parent',
                npe4__Status__c        = 'Current'
            ));
        }

        // ── 5. Single DML. NPSP's List Setting trigger creates the reciprocal
        //       (parent → child with Son / Daughter / Child) automatically.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
