public with sharing class RecordAccessService {
    private static final Integer CHUNK_SIZE = 100;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        List<Id> ids = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                ids.add(recordId);
            }
        }

        if (ids.isEmpty()) {
            return result;
        }

        for (Integer i = 0; i < ids.size(); i += CHUNK_SIZE) {
            Integer upperBound = Math.min(ids.size(), i + CHUNK_SIZE);
            List<Id> chunk = new List<Id>();
            for (Integer j = i; j < upperBound; j++) {
                chunk.add(ids[j]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE HasEditAccess = true
                  AND UserId = :UserInfo.getUserId()
                  AND RecordId IN :chunk
            ]) {
                result.add(access.RecordId);
            }
        }

        return result;
    }
}
