public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    private static final String CUSTOMER_DIRECT = 'Customer - Direct';
    private static final String CUSTOMER_CHANNEL = 'Customer - Channel';

    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        List<Task> tasksToInsert = new List<Task>();
        Date onboardingDueDate = Date.today().addDays(7);

        for (SObject record : triggerNew) {
            Account newAccount = (Account)record;

            if (
                newAccount.Type == CUSTOMER_DIRECT ||
                newAccount.Type == CUSTOMER_CHANNEL
            ) {
                tasksToInsert.add(
                    new Task(
                        Subject = 'Onboard new customer',
                        WhatId = newAccount.Id,
                        OwnerId = newAccount.OwnerId,
                        ActivityDate = onboardingDueDate,
                        Status = 'Not Started',
                        Priority = 'Normal'
                    )
                );
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
