public class AccountOwnershipService {

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        // Bypass all Account trigger actions for the duration of this method
        TriggerBase.bypass('Account');
        try {
            // DML 1: Update Account owners – no SOQL needed; sObjects built from Id set
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accountId : accountIds) {
                accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }
            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate;
            }

            // SOQL 1: Retrieve Contacts belonging to the given Accounts
            List<Contact> contacts = [SELECT Id FROM Contact WHERE AccountId IN :accountIds];

            // DML 2: Update Contact owners – Contact trigger actions run normally
            List<Contact> contactsToUpdate = new List<Contact>();
            for (Contact c : contacts) {
                contactsToUpdate.add(new Contact(Id = c.Id, OwnerId = newOwnerId));
            }
            if (!contactsToUpdate.isEmpty()) {
                update contactsToUpdate;
            }
        } finally {
            // Always restore Account automation, regardless of success or failure
            TriggerBase.clearBypass('Account');
        }
    }
}
