/**
 * After-update trigger action: creates an "Amount changed" Task whenever the
 * Amount field differs between triggerOld and triggerNew.
 *
 * Registered at Order__c = 10 (before TA_Opportunity_RoundAmount at Order 20).
 * A transaction-scoped static Set guards against duplicate tasks caused by the
 * rounding action re-entering the after-update context.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    // Ids that already received an audit task in this execution context.
    // Prevents the recursive after-update triggered by TA_Opportunity_RoundAmount
    // (Order 20) from logging the same user-initiated change a second time.
    private static Set<Id> processedIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        // Build an old-map for cheap look-ups (handles 200+ records).
        Map<Id, SObject> oldMap = new Map<Id, SObject>(triggerOld);

        List<Task> tasksToInsert = new List<Task>();

        for (SObject record : triggerNew) {
            Opportunity opp = (Opportunity) record;

            // Skip records already handled in this transaction (recursion guard).
            if (processedIds.contains(opp.Id)) {
                continue;
            }

            Opportunity oldOpp = (Opportunity) oldMap.get(opp.Id);
            if (oldOpp == null) {
                continue;
            }

            // Only log genuine Amount changes (null-safe comparison).
            if (opp.Amount != oldOpp.Amount) {
                tasksToInsert.add(new Task(
                    Subject = 'Amount changed',
                    WhatId  = opp.Id,
                    Status  = 'Completed'
                ));
                processedIds.add(opp.Id);
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
